import Foundation
@testable import ReachyKit
import Testing

@MainActor
@Suite("An app's own settings page")
struct AppSettingsURLTests {
    /// The robot's host, the app's port — the same split `conversationTurns(for:)`
    /// makes, and for the same reason: `custom_app_url`'s host is `0.0.0.0`, which
    /// dialled from a phone is the phone.
    ///
    /// The app here is deliberately **not** on 7860, so a version that ignored the
    /// declared port and hardcoded the default could not pass this.
    @Test("keeps the robot's host and takes only the app's port")
    func combinesRobotHostWithAppPort() {
        let session = RobotSession.preview(address: RobotAddress(host: "reachy-mini.local", port: 8000))
        let app = RobotApp.preview(
            name: "reachy_mini_conversation_app",
            installed: true,
            customAppURL: "http://0.0.0.0:8123/"
        )

        #expect(session.appSettingsURL(for: app)?.absoluteString == "http://reachy-mini.local:8123/")
    }

    /// Bracketed, because `URLComponents` rejects a bare IPv6 literal in `host`
    /// (project rule 5, and upstream issue #269 was exactly this).
    @Test("brackets an IPv6 robot")
    func bracketsIPv6() {
        let session = RobotSession.preview(address: RobotAddress(host: "fd00::1", port: 8000))
        let app = RobotApp.preview(
            name: "reachy_mini_conversation_app",
            installed: true,
            customAppURL: "http://0.0.0.0:7860/"
        )

        #expect(session.appSettingsURL(for: app)?.absoluteString == "http://[fd00::1]:7860/")
    }

    /// **No fallback to 7860 here**, unlike `ConversationRPCClient`. That one is a
    /// background stream whose failure nobody sees; this one becomes a row someone
    /// taps, and a row leading to a port nothing listens on is worse than no row.
    /// The absent key is the daemon's only signal that an app serves no page.
    @Test("offers nothing for an app that declared no port", arguments: [
        nil,
        "http://0.0.0.0",
        "",
    ] as [String?])
    func requiresADeclaredPort(customAppURL: String?) {
        let session = RobotSession.preview()
        let app = RobotApp.preview(
            name: "reachy_mini_dance",
            installed: true,
            customAppURL: customAppURL
        )

        #expect(session.appSettingsURL(for: app) == nil)
    }

    /// The page is served by the app process on the robot's own network, and the
    /// relay does not carry it — the same boundary that leaves
    /// `RunningAppModel.conversationStreamKey` nil over a remote session.
    @Test("offers nothing over a relay session")
    func requiresALANAddress() {
        let session = RobotSession.preview(link: .remote)
        let app = RobotApp.preview(
            name: "reachy_mini_conversation_app",
            installed: true,
            customAppURL: "http://0.0.0.0:7860/"
        )

        #expect(session.appSettingsURL(for: app) == nil)
    }
}

import Foundation
@testable import ReachyKit
import ReachyTestSupport
import Testing

/// `/cache/*` mounts at the app root and only under `--wireless-version`, like
/// `/wifi/*` and `/update/*`, so it is absent from the committed OpenAPI spec and
/// `sim-daemon` cannot serve it either. Stubs and real hardware are the whole of
/// the coverage.
@Suite("Cache maintenance over HTTP")
struct RobotConnectionCacheTests {
    private func makeConnection(_ session: URLSession) throws -> RobotConnection {
        try RobotConnection(address: RobotAddress(host: "10.42.0.1"), session: session)
    }

    /// The path carries no `/api` prefix. Getting that wrong is the one mistake
    /// these two routes invite, and it would 404 — which this client reads as a
    /// Lite robot rather than as a typo.
    @Test("clearing the Hugging Face cache POSTs to the root-mounted route")
    func clearsTheHuggingFaceCache() async throws {
        let session = StubURLProtocol.makeSession([
            "/cache/clear-hf": .init(
                statusCode: 200,
                json: #"{"status":"success","message":"HuggingFace cache cleared"}"#
            ),
        ])

        try await makeConnection(session).clearHuggingFaceCache()

        let request = StubURLProtocol.requests(for: session).first
        #expect(request?.httpMethod == "POST")
        #expect(request?.url?.path == "/cache/clear-hf")
    }

    @Test("uninstalling every app POSTs to reset-apps")
    func resetsApps() async throws {
        let session = StubURLProtocol.makeSession([
            "/cache/reset-apps": .init(
                statusCode: 200,
                json: #"{"status":"success","message":"Applications virtual environment removed"}"#
            ),
        ])

        try await makeConnection(session).resetApps()

        let request = StubURLProtocol.requests(for: session).first
        #expect(request?.httpMethod == "POST")
        #expect(request?.url?.path == "/cache/reset-apps")
    }

    /// The daemon answers 200 with a different `message` when the directory was
    /// already gone. Both are success, and the client drops the sentence rather
    /// than putting the daemon's English on a screen it cannot translate.
    @Test("an already-empty directory is a success, not a failure")
    func acceptsAnAlreadyEmptyDirectory() async throws {
        let session = StubURLProtocol.makeSession([
            "/cache/reset-apps": .init(
                statusCode: 200,
                json: #"{"status":"success","message":"Virtual environment directory already empty"}"#
            ),
        ])

        try await makeConnection(session).resetApps()
    }

    /// A Lite robot never mounts the router, so 404 here means the feature is
    /// absent rather than the resource — the same reading `/wifi/*` gets.
    @Test("a Lite robot's 404 reports the feature as unavailable")
    func reportsAnUnmountedRouterAsUnavailable() async throws {
        let session = StubURLProtocol.makeSession(["/cache/clear-hf": .init(statusCode: 404)])
        let connection = try makeConnection(session)

        await #expect(throws: ReachyKitError.wirelessFeaturesUnavailable) {
            try await connection.clearHuggingFaceCache()
        }
    }

    /// `shutil.rmtree` failing comes back as a 500 with a `detail`, which is the
    /// only way the robot reports that it could not delete something.
    @Test("a failed delete surfaces as a rejection")
    func surfacesAFailedDelete() async throws {
        let session = StubURLProtocol.makeSession([
            "/cache/reset-apps": .init(statusCode: 500, json: #"{"detail":"Failed to clear virtual environment"}"#),
        ])
        let connection = try makeConnection(session)

        await #expect(throws: (any Error).self) {
            try await connection.resetApps()
        }
    }
}

import Foundation
import ReachyKit
@testable import ReachyUI
import Testing

/// Records what the card asked the robot to delete, and can refuse.
private final class MaintenanceRecorder: @unchecked Sendable {
    var calls: [String] = []
    var failure: (any Error)?
}

/// A client speaking both protocols a session needs here: the four members every
/// double must supply, and `/cache/*` — which is what `canPerformMaintenance`
/// looks for.
private struct MaintenanceCapableClient: RobotAPIClient, CacheMaintenanceClient {
    let recorder: MaintenanceRecorder
    private let base = PreviewRobotClient()

    func handshake() async throws -> RobotConnection.Handshake {
        try await base.handshake()
    }

    func daemonStatus() async throws -> Components.Schemas.DaemonStatus {
        try await base.daemonStatus()
    }

    func wakeUp() async throws -> String {
        try await base.wakeUp()
    }

    func gotoSleep() async throws -> String {
        try await base.gotoSleep()
    }

    func clearHuggingFaceCache() async throws {
        recorder.calls.append("clear-hf")
        if let failure = recorder.failure { throw failure }
    }

    func resetApps() async throws {
        recorder.calls.append("reset-apps")
        if let failure = recorder.failure { throw failure }
    }
}

@MainActor
@Suite("Robot maintenance", .timeLimit(.minutes(1)))
struct MaintenanceModelTests {
    private struct Refused: Error, LocalizedError {
        var errorDescription: String? { "The robot could not delete it." }
    }

    private func session(
        recorder: MaintenanceRecorder = MaintenanceRecorder(),
        runningApp: RobotAppStatus? = nil,
        wirelessVersion: Bool = true
    ) -> RobotSession {
        .preview(
            status: .preview(wirelessVersion: wirelessVersion),
            runningApp: runningApp,
            client: MaintenanceCapableClient(recorder: recorder)
        )
    }

    @Test("the section is offered only by a robot that mounts the routes")
    func offeredOnlyByAWirelessRobot() {
        #expect(session().canPerformMaintenance)
        #expect(!session(wirelessVersion: false).canPerformMaintenance)
        // A client that does not speak the protocol at all — every Lite robot and
        // every relay session.
        #expect(!RobotSession.preview().canPerformMaintenance)
    }

    /// The daemon deletes `/venvs/apps_venv/` without stopping anything first, so
    /// the interpreter a live app is running in goes away underneath it. Nothing
    /// on the robot prevents that; this is the only place it is prevented.
    @Test("a busy app blocks the uninstall", arguments: [
        RobotAppStatus.State.running,
        .starting,
        .stopping,
        .unknown("reloading"),
    ])
    func blocksWhileAnAppHoldsTheRobot(state: RobotAppStatus.State) {
        let status = RobotAppStatus.preview(state)

        #expect(MaintenanceModel().blockingApp(session(runningApp: status))?.name == status.app.name)
    }

    @Test("a finished or crashed app does not block it", arguments: [
        RobotAppStatus.State.done,
        .error,
    ])
    func allowsOnceTheAppIsOver(state: RobotAppStatus.State) {
        #expect(MaintenanceModel().blockingApp(session(runningApp: .preview(state))) == nil)
    }

    @Test("nothing running blocks nothing")
    func allowsWithNoApp() {
        #expect(MaintenanceModel().blockingApp(session()) == nil)
    }

    @Test("each action calls its own route and reports when it is done")
    func performsTheChosenAction() async {
        let recorder = MaintenanceRecorder()
        let session = session(recorder: recorder)
        let model = MaintenanceModel()

        await model.perform(.clearHuggingFaceCache, session: session)

        #expect(recorder.calls == ["clear-hf"])
        #expect(model.finished == .clearHuggingFaceCache)
        #expect(model.lastError == nil)
        #expect(!model.isBusy)

        await model.perform(.resetApps, session: session)

        #expect(recorder.calls == ["clear-hf", "reset-apps"])
        #expect(model.finished == .resetApps)
    }

    /// The failure belongs to this card, not to `RobotSession.robotError` — a
    /// maintenance call that refused says nothing about the robot's connection or
    /// its power.
    @Test("a refusal fills this card's own slot and claims nothing finished")
    func reportsARefusal() async {
        let recorder = MaintenanceRecorder()
        recorder.failure = Refused()
        let session = session(recorder: recorder)
        let model = MaintenanceModel()

        await model.perform(.resetApps, session: session)

        #expect(model.lastError == "The robot could not delete it.")
        #expect(model.finished == nil)
        #expect(session.robotError == nil)
        #expect(!model.isBusy)
    }
}

