150	    /// this requirement to the main actor, but a nonisolated witness would satisfy
151	    /// them and then fail to construct one.
152	    @MainActor
153	    func makeCoordinator() -> Coordinator {
154	        Coordinator()
155	    }
156	}
157	
158	#if os(iOS)
159	    extension AppSettingsWebView: UIViewRepresentable {
160	        func makeUIView(context: Context) -> WKWebView {
161	            makeWebView(context.coordinator)
162	        }
163	
164	        func updateUIView(_ webView: WKWebView, context: Context) {
165	            load(into: webView, context.coordinator)
166	        }
167	    }
168	#else
169	    extension AppSettingsWebView: NSViewRepresentable {
170	        func makeNSView(context: Context) -> WKWebView {
171	            makeWebView(context.coordinator)
172	        }
173	
174	        func updateNSView(_ webView: WKWebView, context: Context) {
175	            load(into: webView, context.coordinator)
176	        }
